def eval(self, orig):
        """
        Apply the less or equal algorithm on the ordered list of metadata
        statements

        :param orig: Start values
        :return:
        """
        _le = {}
        _err = []
        for k, v in self.sup_items():
            if k in DoNotCompare:
                continue
            if k in orig:
                if is_lesser(orig[k], v):
