        elif status == 404:
            raise ibmiotf.APIException(404, "A draft thing type with the specified id does not exist.", None)
        elif status == 500:
            raise ibmiotf.APIException(500, "Unexpected error", None)
        else:
            raise ibmiotf.APIException(None, "Unexpected error", None)

