        c_c = mm.select_any('C_C', where(Name=name))
        if c_c:
            return mk_component(mm, c_c, derived_attributes)
        elif name:
            raise OoaOfOoaException('Unable to find the component %s' % name)
        else:
            return mk_component(mm, c_c, derived_attributes)

