def get_all_mechs():
    """
    Return an :class:`OIDSet` of all the mechanisms supported by the underlying GSSAPI
    implementation.
    """
    minor_status = ffi.new('OM_uint32[1]')
    mech_set = ffi.new('gss_OID_set[1]')
